<span class="line"><span style="color:#D73A49">    throw</span><span style="color:#6F42C1"> getJSONParseError</span><span style="color:#5a32a3">(</span><span style="color:#24292E">sv, </span><span style="color:#032F62">"EOF"</span><span style="color:#5a32a3">)</span><span style="color:#24292E">;</span><span style="color:#6A737D"> // 希望整个 json 只有一个 root node</span></span>
